<script>
  /* ── MOBILE NAV ── */
  function toggleMenu() {
    const nav = document.getElementById('main-nav');
    nav.classList.toggle('open');
  }

  /* ── CAROUSEL ── */
  const track = document.getElementById('carouselTrack');
  const dotsContainer = document.getElementById('carouselDots');
  let currentPage = 0;

  function getPerPage() {
    const w = window.innerWidth;
    if (w <= 480) return 1;
    if (w <= 720) return 2;
    if (w <= 1080) return 3;
    return 4;
  }

  function totalPages() {
    return Math.ceil(track.children.length / getPerPage());
  }

  function buildDots() {
    dotsContainer.innerHTML = '';
    for (let i = 0; i < totalPages(); i++) {
      const d = document.createElement('button');
      d.className = 'carousel-dot' + (i === currentPage ? ' active' : '');
      d.setAttribute('aria-label', `Go to page ${i + 1}`);
      d.onclick = () => goToPage(i);
      dotsContainer.appendChild(d);
    }
  }

  function goToPage(page) {
    const perPage = getPerPage();
    const tp = totalPages();
    currentPage = Math.max(0, Math.min(page, tp - 1));
    const gap = 20;
    const cardWidth = track.children[0].getBoundingClientRect().width;
    const offset = currentPage * perPage * (cardWidth + gap);
    track.style.transform = `translateX(-${offset}px)`;
    document.querySelectorAll('.carousel-dot').forEach((d, i) => {
      d.classList.toggle('active', i === currentPage);
    });
    document.getElementById('prevBtn').disabled = currentPage === 0;
    document.getElementById('nextBtn').disabled = currentPage >= tp - 1;
  }

  function slideCarousel(dir) {
    goToPage(currentPage + dir);
  }

  window.addEventListener('resize', () => {
    currentPage = 0;
    buildDots();
    goToPage(0);
  });

  buildDots();

  /* ── STORE SEARCH ── */
  function searchStores() {
    const val = document.getElementById('zipInput').value.trim();
    if (!val) {
      document.getElementById('zipInput').focus();
      return;
    }
    const results = document.getElementById('storeResults');
    results.classList.remove('visible');
    setTimeout(() => results.classList.add('visible'), 300);
  }

  document.getElementById('zipInput').addEventListener('keydown', function(e) {
    if (e.key === 'Enter') searchStores();
  });

  /* ── NEWSLETTER ── */
  function subscribeNewsletter() {
    const email = document.getElementById('emailInput').value.trim();
    if (!email || !email.includes('@')) {
      document.getElementById('emailInput').focus();
      return;
    }
    document.getElementById('emailInput').value = '';
    document.getElementById('newsletterConfirm').classList.add('visible');
  }

  document.getElementById('emailInput').addEventListener('keydown', function(e) {
    if (e.key === 'Enter') subscribeNewsletter();
  });

  /* ── SCROLL HELPER ── */
  function scrollToLocator() {
    document.getElementById('store-locator').scrollIntoView({ behavior: 'smooth' });
  }
</script>
